import * as THREE from 'three/webgpu';
import { mix, positionWorld, float, uniform } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const panelWidth = 3.4;
  const panelHeight = 1.9;
  const cornerRadius = 0.06;

  // Design colors
  const colorTopHex = '#1a1a22';
  const colorBottomHex = '#111116';
  const borderColorHex = '#26262f';
  const accentColorHex = '#ff2a38';
  const textColorHex = '#e8ecf2';

  // Panel geometry with rounded corners
  const panelGeom = createRoundedRectGeometry(panelWidth, panelHeight, cornerRadius);

  // Create gradient color node for panel using TSL
  const colorTop = uniform(new THREE.Color(colorTopHex));
  const colorBottom = uniform(new THREE.Color(colorBottomHex));
  const panelColorNode = mix(
    colorBottom,
    colorTop,
    positionWorld.y.add(float(panelHeight / 2)).div(float(panelHeight))
  );

  const panelMat = new THREE.MeshStandardNodeMaterial({
    colorNode: panelColorNode,
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    transparent: true,
  });

  const panelMesh = new THREE.Mesh(panelGeom, panelMat);
  panelMesh.position.z = 0;
  group.add(panelMesh);

  // Hairline border
  const borderGeom = createRoundedRectGeometry(
    panelWidth - 0.012,
    panelHeight - 0.012,
    cornerRadius
  );
  const borderMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(borderColorHex),
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
  });
  const borderMesh = new THREE.Mesh(borderGeom, borderMat);
  borderMesh.position.z = 0.002;
  group.add(borderMesh);

  // Create quotation mark
  const quoteMark = ctx.fontAtlas.create({
    text: '"',
    fontFamily: 'Lora',
    fontSize: 0.62,
    fontWeight: 600,
  });
  if (quoteMark) {
    quoteMark.position.set(-panelWidth / 2 + 0.5, panelHeight / 2 - 0.5, 0.04);
    quoteMark.traverse(child => {
      if (child instanceof THREE.Mesh && child.material) {
        child.material = new THREE.MeshStandardNodeMaterial({
          color: new THREE.Color(accentColorHex),
          roughness: 0.5,
          metalness: 0.3,
        });
      }
    });
    group.add(quoteMark);
  }

  // Quote text
  const quoteText = ctx.fontAtlas.create({
    text: 'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    fontFamily: 'Lora',
    fontSize: 0.20,
    fontWeight: 400,
  });
  if (quoteText) {
    quoteText.position.set(-panelWidth / 2 + 0.5, panelHeight / 2 - 0.75, 0.03);
    quoteText.traverse(child => {
      if (child instanceof THREE.Mesh && child.material) {
        child.material = new THREE.MeshStandardNodeMaterial({
          color: new THREE.Color(textColorHex),
          roughness: 0.4,
          metalness: 0,
        });
      }
    });
    group.add(quoteText);
  }

  // Accent rule separator
  const ruleGeom = new THREE.PlaneGeometry(0.2, 0.02);
  const ruleMat = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(accentColorHex),
    emissive: new THREE.Color(accentColorHex),
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0,
  });
  const accentRule = new THREE.Mesh(ruleGeom, ruleMat);
  accentRule.position.set(-panelWidth / 2 + 0.35, panelHeight / 2 - 1.32, 0.03);
  group.add(accentRule);

  // Attribution text
  const attribution = ctx.fontAtlas.create({
    text: 'M. OKAFOR',
    fontFamily: 'JetBrains Mono',
    fontSize: 0.13,
    fontWeight: 700,
  });
  if (attribution) {
    attribution.position.set(-panelWidth / 2 + 0.55, panelHeight / 2 - 1.32, 0.03);
    attribution.traverse(child => {
      if (child instanceof THREE.Mesh && child.material) {
        child.material = new THREE.MeshStandardNodeMaterial({
          color: new THREE.Color(textColorHex),
          roughness: 0.4,
          metalness: 0,
        });
      }
    });
    group.add(attribution);
  }

  // Caption text
  const caption = ctx.fontAtlas.create({
    text: 'COLLECTOR SINCE 2019',
    fontFamily: 'JetBrains Mono',
    fontSize: 0.09,
    fontWeight: 400,
  });
  if (caption) {
    caption.position.set(-panelWidth / 2 + 0.55, panelHeight / 2 - 1.42, 0.03);
    caption.traverse(child => {
      if (child instanceof THREE.Mesh && child.material) {
        child.material = new THREE.MeshStandardNodeMaterial({
          color: new THREE.Color(textColorHex),
          roughness: 0.4,
          metalness: 0,
        });
      }
    });
    group.add(caption);
  }

  // Apply scene position
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x || 0,
      config.scenePosition.y || 0,
      config.scenePosition.z || 0
    );
    if (config.scenePosition.rotationXYZ) {
      group.rotation.set(
        config.scenePosition.rotationXYZ[0] || 0,
        config.scenePosition.rotationXYZ[1] || 0,
        config.scenePosition.rotationXYZ[2] || 0
      );
    }
    if (config.scenePosition.scaleXYZ) {
      group.scale.set(
        config.scenePosition.scaleXYZ[0] || 1,
        config.scenePosition.scaleXYZ[1] || 1,
        config.scenePosition.scaleXYZ[2] || 1
      );
    }
  }

  // Setup animations
  const startY = group.position.y;
  const timeline = gsap.timeline();

  // Panel fade-up: y +0.2 -> 0, opacity 0 -> 1
  group.userData.opacity = 0;
  timeline.from(group.position, {
    y: startY + 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);

  timeline.from(group.userData, {
    opacity: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    onUpdate() {
      const opacity = group.userData.opacity;
      group.traverse(child => {
        if (child instanceof THREE.Mesh && child.material) {
          child.material.opacity = opacity;
        }
      });
    },
  }, 0);

  // Quote mark weighted-settle: scale 1.04 -> 1.0
  if (quoteMark) {
    quoteMark.scale.set(1.04, 1.04, 1.04);
    timeline.to(quoteMark.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    }, 0.5);
  }

  // Cleanup
  group.userData.cleanup = () => {
    timeline.kill();
    panelGeom.dispose();
    panelMat.dispose();
    borderGeom.dispose();
    borderMat.dispose();
    ruleGeom.dispose();
    ruleMat.dispose();

    group.traverse(child => {
      if (child instanceof THREE.Mesh) {
        if (child.geometry && 
            child.geometry !== panelGeom && 
            child.geometry !== borderGeom && 
            child.geometry !== ruleGeom) {
          child.geometry.dispose();
        }
        if (child.material) {
          child.material.dispose();
        }
      }
    });
  };

  group.userData.handlers = {};

  return group;
}

function createRoundedRectGeometry(width, height, radius, segments = 16) {
  const shape = new THREE.Shape();

  // Trace rounded rectangle path
  shape.moveTo(-width / 2 + radius, -height / 2);
  shape.lineTo(width / 2 - radius, -height / 2);
  shape.quadraticCurveTo(width / 2, -height / 2, width / 2, -height / 2 + radius);
  shape.lineTo(width / 2, height / 2 - radius);
  shape.quadraticCurveTo(width / 2, height / 2, width / 2 - radius, height / 2);
  shape.lineTo(-width / 2 + radius, height / 2);
  shape.quadraticCurveTo(-width / 2, height / 2, -width / 2, height / 2 - radius);
  shape.lineTo(-width / 2, -height / 2 + radius);
  shape.quadraticCurveTo(-width / 2, -height / 2, -width / 2 + radius, -height / 2);

  return new THREE.ShapeGeometry(shape, segments);
}
